1  import React, {useMemo} from 'react';
     2  import {View} from 'react-native';
     3  import type {OnyxEntry} from 'react-native-onyx';
     4  import {withOnyx} from 'react-native-onyx';
     5  import useLocalize from '@hooks/useLocalize';
     6  import useThemeStyles from '@hooks/useThemeStyles';
     7  import Navigation from '@libs/Navigation/Navigation';
     8  import * as OptionsListUtils from '@libs/OptionsListUtils';
     9  import * as ReportUtils from '@libs/ReportUtils';
    10  import SidebarUtils from '@libs/SidebarUtils';
    11  import CONST from '@src/CONST';
    12  import type {IOUType} from '@src/CONST';
    13  import ONYXKEYS from '@src/ONYXKEYS';
    14  import ROUTES from '@src/ROUTES';
    15  import type {PersonalDetailsList, Policy, Report} from '@src/types/onyx';
    16  import {PressableWithoutFeedback} from './Pressable';
    17  import RenderHTML from './RenderHTML';
    18  import Text from './Text';
    19  import UserDetailsTooltip from './UserDetailsTooltip';
    20
    21  type ReportWelcomeTextOnyxProps = {
    22      /** All of the personal details for everyone */
    23      personalDetails: OnyxEntry<PersonalDetailsList>;
    24  };
    25
    26  type ReportWelcomeTextProps = ReportWelcomeTextOnyxProps & {
    27      /** The report currently being looked at */
    28      report: OnyxEntry<Report>;
    29
    30      /** The policy for the current route */
    31      policy: OnyxEntry<Policy>;
    32  };
    33
    34  function ReportWelcomeText({report, policy, personalDetails}: ReportWelcomeTextProps) {
    35      const {translate} = useLocalize();
    36      const styles = useThemeStyles();
    37      const isPolicyExpenseChat = ReportUtils.isPolicyExpenseChat(report);
    38      const isChatRoom = ReportUtils.isChatRoom(report);
    39      const isSelfDM = ReportUtils.isSelfDM(report);
    40      const isInvoiceRoom = ReportUtils.isInvoiceRoom(report);
    41      const isSystemChat = ReportUtils.isSystemChat(report);
    42      const isDefault = !(isChatRoom || isPolicyExpenseChat || isSelfDM || isInvoiceRoom || isSystemChat);
    43      const participantAccountIDs = ReportUtils.getParticipantsAccountIDsForDisplay(report);
    44      const isMultipleParticipant = participantAccountIDs.length > 1;
    45      const displayNamesWithTooltips = ReportUtils.getDisplayNamesWithTooltips(OptionsListUtils.getPersonalDetailsForAccountIDs(participantAccountIDs, personalDetails), isMultipleParticipant);
    46      const welcomeMessage = SidebarUtils.getWelcomeMessage(report, policy);
    47      const moneyRequestOptions = ReportUtils.temporary_getMoneyRequestOptions(report, policy, participantAccountIDs);
    48      const additionalText = moneyRequestOptions
    49          .filter((item): item is Exclude<IOUType, typeof CONST.IOU.TYPE.REQUEST | typeof CONST.IOU.TYPE.SEND | typeof CONST.IOU.TYPE.INVOICE> => item !== CONST.IOU.TYPE.INVOICE)
    50          .map((item) => translate(`reportActionsView.iouTypes.${item}`))
    51          .join(', ');
    52      const canEditPolicyDescription = ReportUtils.canEditPolicyDescription(policy);
    53      const reportName = ReportUtils.getReportName(report);
    54
    55      const navigateToReport = () => {
    56          if (!report?.reportID) {
    57              return;
    58          }
    59
    60          Navigation.navigate(ROUTES.REPORT_WITH_ID_DETAILS.getRoute(report.reportID, Navigation.getReportRHPActiveRoute()));
    61      };
    62
    63      const welcomeHeroText = useMemo(() => {
    64          if (isInvoiceRoom) {
    65              return translate('reportActionsView.sayHello');
    66          }
    67
    68          if (isChatRoom) {
    69              return translate('reportActionsView.welcomeToRoom', {roomName: reportName});
    70          }
    71
    72          if (isSelfDM) {
    73              return translate('reportActionsView.yourSpace');
    74          }
    75
    76          if (isSystemChat) {
    77              return reportName;
    78          }
    79
    80          return translate('reportActionsView.sayHello');
    81      }, [isChatRoom, isInvoiceRoom, isSelfDM, isSystemChat, translate, reportName]);
    82
    83      return (
    84          <>
    85              <View>
    86                  <Text style={[styles.textHero]}>{welcomeHeroText}</Text>
    87              </View>
    88              <View style={[styles.mt3, styles.mw100]}>
    89                  {isPolicyExpenseChat &&
    90                      (welcomeMessage?.messageHtml ? (
    91                          <PressableWithoutFeedback
    92                              onPress={() => {
    93                                  if (!canEditPolicyDescription) {
    94                                      return;
    95                                  }
    96                                  Navigation.navigate(ROUTES.WORKSPACE_PROFILE_DESCRIPTION.getRoute(policy?.id ?? '-1'));
    97                              }}
    98                              style={[styles.renderHTML, canEditPolicyDescription ? styles.cursorPointer : styles.cursorText]}
    99                              accessibilityLabel={translate('reportDescriptionPage.roomDescription')}
   100                          >
   101                              <RenderHTML html={welcomeMessage.messageHtml} />
   102                          </PressableWithoutFeedback>
   103                      ) : (
   104                          <Text>
   105                              <Text>{welcomeMessage.phrase1}</Text>
   106                              <Text style={[styles.textStrong]}>{ReportUtils.getDisplayNameForParticipant(report?.ownerAccountID)}</Text>
   107                              <Text>{welcomeMessage.phrase2}</Text>
   108                              <Text style={[styles.textStrong]}>{ReportUtils.getPolicyName(report)}</Text>
   109                              <Text>{welcomeMessage.phrase3}</Text>
   110                          </Text>
   111                      ))}
   112                  {isChatRoom &&
   113                      (welcomeMessage?.messageHtml ? (
   114                          <PressableWithoutFeedback
   115                              onPress={() => {
   116                                  const activeRoute = Navigation.getReportRHPActiveRoute();
   117                                  if (ReportUtils.canEditReportDescription(report, policy)) {
   118                                      Navigation.navigate(ROUTES.REPORT_DESCRIPTION.getRoute(report?.reportID ?? '-1', activeRoute));
   119                                      return;
   120                                  }
   121                                  Navigation.navigate(ROUTES.REPORT_WITH_ID_DETAILS.getRoute(report?.reportID ?? '-1', activeRoute));
   122                              }}
   123                              style={styles.renderHTML}
   124                              accessibilityLabel={translate('reportDescriptionPage.roomDescription')}
   125                          >
   126                              <RenderHTML html={welcomeMessage.messageHtml} />
   127                          </PressableWithoutFeedback>
   128                      ) : (
   129                          <Text>
   130                              <Text>{welcomeMessage.phrase1}</Text>
   131                              {welcomeMessage.showReportName && (
   132                                  <Text
   133                                      style={[styles.textStrong]}
   134                                      onPress={navigateToReport}
   135                                      suppressHighlighting
   136                                  >
   137                                      {ReportUtils.getReportName(report)}
   138                                  </Text>
   139                              )}
   140                              {welcomeMessage.phrase2 !== undefined && <Text>{welcomeMessage.phrase2}</Text>}
   141                          </Text>
   142                      ))}
   143                  {isSelfDM && (
   144                      <Text>
   145                          <Text>{welcomeMessage.phrase1}</Text>
   146                      </Text>
   147                  )}
   148                  {isSystemChat && (
   149                      <Text>
   150                          <Text>{welcomeMessage.phrase1}</Text>
   151                      </Text>
   152                  )}
   153                  {isDefault && (
   154                      <Text>
   155                          <Text>{welcomeMessage.phrase1}</Text>
   156                          {displayNamesWithTooltips.map(({displayName, accountID}, index) => (
   157                              // eslint-disable-next-line react/no-array-index-key
   158                              <Text key={`${displayName}${index}`}>
   159                                  <UserDetailsTooltip accountID={accountID}>
   160                                      {ReportUtils.isOptimisticPersonalDetail(accountID) ? (
   161                                          <Text style={[styles.textStrong]}>{displayName}</Text>
   162                                      ) : (
   163                                          <Text
   164                                              style={[styles.textStrong]}
   165                                              onPress={() => Navigation.navigate(ROUTES.PROFILE.getRoute(accountID, Navigation.getReportRHPActiveRoute()))}
   166                                              suppressHighlighting
   167                                          >
   168                                              {displayName}
   169                                          </Text>
   170                                      )}
   171                                  </UserDetailsTooltip>
   172                                  {index === displayNamesWithTooltips.length - 1 && <Text>.</Text>}
   173                                  {index === displayNamesWithTooltips.length - 2 && <Text>{` ${translate('common.and')} `}</Text>}
   174                                  {index < displayNamesWithTooltips.length - 2 && <Text>, </Text>}
   175                              </Text>
   176                          ))}
   177                      </Text>
   178                  )}
   179                  {(moneyRequestOptions.includes(CONST.IOU.TYPE.PAY) || moneyRequestOptions.includes(CONST.IOU.TYPE.SUBMIT) || moneyRequestOptions.includes(CONST.IOU.TYPE.TRACK)) && (
   180                      <Text>{translate('reportActionsView.usePlusButton', {additionalText})}</Text>
   181                  )}
   182              </View>
   183          </>
   184      );
   185  }
   186
   187  ReportWelcomeText.displayName = 'ReportWelcomeText';
   188
   189  export default withOnyx<ReportWelcomeTextProps, ReportWelcomeTextOnyxProps>({
   190      personalDetails: {
   191          key: ONYXKEYS.PERSONAL_DETAILS_LIST,
   192      },
   193  })(ReportWelcomeText);

1  import {Str} from 'expensify-common';
     2  import type {OnyxCollection, OnyxEntry} from 'react-native-onyx';
     3  import Onyx from 'react-native-onyx';
     4  import type {PolicySelector, ReportActionsSelector} from '@hooks/useReportIDs';
     5  import CONST from '@src/CONST';
     6  import ONYXKEYS from '@src/ONYXKEYS';
     7  import type {PersonalDetails, PersonalDetailsList, ReportActions, TransactionViolation} from '@src/types/onyx';
     8  import type Beta from '@src/types/onyx/Beta';
     9  import type Policy from '@src/types/onyx/Policy';
    10  import type PriorityMode from '@src/types/onyx/PriorityMode';
    11  import type Report from '@src/types/onyx/Report';
    12  import type ReportAction from '@src/types/onyx/ReportAction';
    13  import type DeepValueOf from '@src/types/utils/DeepValueOf';
    14  import * as CollectionUtils from './CollectionUtils';
    15  import {hasValidDraftComment} from './DraftCommentUtils';
    16  import localeCompare from './LocaleCompare';
    17  import * as LocalePhoneNumber from './LocalePhoneNumber';
    18  import * as Localize from './Localize';
    19  import * as OptionsListUtils from './OptionsListUtils';
    20  import Parser from './Parser';
    21  import * as PolicyUtils from './PolicyUtils';
    22  import * as ReportActionsUtils from './ReportActionsUtils';
    23  import * as ReportUtils from './ReportUtils';
    24  import * as TaskUtils from './TaskUtils';
    25
    26  type WelcomeMessage = {showReportName: boolean; phrase1?: string; phrase2?: string; phrase3?: string; messageText?: string; messageHtml?: string};
    27
    28  const visibleReportActionItems: ReportActions = {};
    29  let allPersonalDetails: OnyxEntry<PersonalDetailsList>;
    30  Onyx.connect({
    31      key: ONYXKEYS.PERSONAL_DETAILS_LIST,
    32      callback: (value) => {
    33          allPersonalDetails = value ?? {};
    34      },
    35  });
    36  Onyx.connect({
    37      key: ONYXKEYS.COLLECTION.REPORT_ACTIONS,
    38      callback: (actions, key) => {
    39          if (!actions || !key) {
    40              return;
    41          }
    42          const reportID = CollectionUtils.extractCollectionItemID(key);
    43
    44          const actionsArray: ReportAction[] = ReportActionsUtils.getSortedReportActions(Object.values(actions));
    45
    46          // The report is only visible if it is the last action not deleted that
    47          // does not match a closed or created state.
    48          const reportActionsForDisplay = actionsArray.filter(
    49              (reportAction) => ReportActionsUtils.shouldReportActionBeVisibleAsLastAction(reportAction) && reportAction.actionName !== CONST.REPORT.ACTIONS.TYPE.CREATED,
    50          );
    51
    52          visibleReportActionItems[reportID] = reportActionsForDisplay[reportActionsForDisplay.length - 1];
    53      },
    54  });
    55
    56  function compareStringDates(a: string, b: string): 0 | 1 | -1 {
    57      if (a < b) {
    58          return -1;
    59      }
    60      if (a > b) {
    61          return 1;
    62      }
    63      return 0;
    64  }
    65
    66  /**
    67   * A mini report object that contains only the necessary information to sort reports.
    68   * This is used to avoid copying the entire report object and only the necessary information.
    69   */
    70  type MiniReport = {
    71      reportID?: string;
    72      displayName: string;
    73      lastVisibleActionCreated?: string;
    74  };
    75
    76  /**
    77   * @returns An array of reportIDs sorted in the proper order
    78   */
    79  function getOrderedReportIDs(
    80      currentReportId: string | null,
    81      allReports: OnyxCollection<Report>,
    82      betas: OnyxEntry<Beta[]>,
    83      policies: OnyxCollection<PolicySelector>,
    84      priorityMode: OnyxEntry<PriorityMode>,
    85      allReportActions: OnyxCollection<ReportActionsSelector>,
    86      transactionViolations: OnyxCollection<TransactionViolation[]>,
    87      currentPolicyID = '',
    88      policyMemberAccountIDs: number[] = [],
    89  ): string[] {
    90      const isInFocusMode = priorityMode === CONST.PRIORITY_MODE.GSD;
    91      const isInDefaultMode = !isInFocusMode;
    92      const allReportsDictValues = Object.values(allReports ?? {});
    93
    94      // Filter out all the reports that shouldn't be displayed
    95      let reportsToDisplay: Array<Report & {hasErrorsOtherThanFailedReceipt?: boolean}> = [];
    96      allReportsDictValues.forEach((report) => {
    97          if (!report) {
    98              return;
    99          }
   100          if ((Object.values(CONST.REPORT.UNSUPPORTED_TYPE) as string[]).includes(report?.type ?? '')) {
   101              return;
   102          }
   103          const reportActions = allReportActions?.[`${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${report.reportID}`] ?? {};
   104          const parentReportAction = ReportActionsUtils.getReportAction(report?.parentReportID ?? '-1', report?.parentReportActionID ?? '-1');
   105          const doesReportHaveViolations = OptionsListUtils.shouldShowViolations(report, transactionViolations);
   106          const isHidden = ReportUtils.getReportNotificationPreference(report) === CONST.REPORT.NOTIFICATION_PREFERENCE.HIDDEN;
   107          const isFocused = report.reportID === currentReportId;
   108          const allReportErrors = OptionsListUtils.getAllReportErrors(report, reportActions) ?? {};
   109          const transactionReportActions = ReportActionsUtils.getAllReportActions(report.reportID);
   110          const oneTransactionThreadReportID = ReportActionsUtils.getOneTransactionThreadReportID(report.reportID, transactionReportActions, undefined);
   111          let doesTransactionThreadReportHasViolations = false;
   112          if (oneTransactionThreadReportID) {
   113              const transactionReport = ReportUtils.getReport(oneTransactionThreadReportID);
   114              doesTransactionThreadReportHasViolations = !!transactionReport && OptionsListUtils.shouldShowViolations(transactionReport, transactionViolations);
   115          }
   116          const hasErrorsOtherThanFailedReceipt =
   117              doesTransactionThreadReportHasViolations ||
   118              doesReportHaveViolations ||
   119              Object.values(allReportErrors).some((error) => error?.[0] !== Localize.translateLocal('iou.error.genericSmartscanFailureMessage'));
   120          const isReportInAccessible = report?.errorFields?.notFound;
   121          if (ReportUtils.isOneTransactionThread(report.reportID, report.parentReportID ?? '0', parentReportAction)) {
   122              return;
   123          }
   124          if (hasErrorsOtherThanFailedReceipt && !isReportInAccessible) {
   125              reportsToDisplay.push({
   126                  ...report,
   127                  hasErrorsOtherThanFailedReceipt: true,
   128              });
   129              return;
   130          }
   131          const isSystemChat = ReportUtils.isSystemChat(report);
   132          const isExpenseReportWithoutParentAccess = ReportUtils.isExpenseReportWithoutParentAccess(report);
   133          const shouldOverrideHidden =
   134              // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
   135              hasValidDraftComment(report.reportID) || hasErrorsOtherThanFailedReceipt || isFocused || isSystemChat || report.isPinned || isExpenseReportWithoutParentAccess;
   136          if (isHidden && !shouldOverrideHidden) {
   137              return;
   138          }
   139
   140          if (
   141              ReportUtils.shouldReportBeInOptionList({
   142                  report,
   143                  currentReportId: currentReportId ?? '-1',
   144                  isInFocusMode,
   145                  betas,
   146                  policies: policies as OnyxCollection<Policy>,
   147                  excludeEmptyChats: true,
   148                  doesReportHaveViolations,
   149                  includeSelfDM: true,
   150              })
   151          ) {
   152              reportsToDisplay.push(report);
   153          }
   154      });
   155
   156      // The LHN is split into five distinct groups, and each group is sorted a little differently. The groups will ALWAYS be in this order:
   157      // 1. Pinned/GBR - Always sorted by reportDisplayName
   158      // 2. Error reports - Always sorted by reportDisplayName
   159      // 3. Drafts - Always sorted by reportDisplayName
   160      // 4. Non-archived reports and settled IOUs
   161      //      - Sorted by lastVisibleActionCreated in default (most recent) view mode
   162      //      - Sorted by reportDisplayName in GSD (focus) view mode
   163      // 5. Archived reports
   164      //      - Sorted by lastVisibleActionCreated in default (most recent) view mode
   165      //      - Sorted by reportDisplayName in GSD (focus) view mode
   166
   167      const pinnedAndGBRReports: MiniReport[] = [];
   168      const errorReports: MiniReport[] = [];
   169      const draftReports: MiniReport[] = [];
   170      const nonArchivedReports: MiniReport[] = [];
   171      const archivedReports: MiniReport[] = [];
   172
   173      if (currentPolicyID || policyMemberAccountIDs.length > 0) {
   174          reportsToDisplay = reportsToDisplay.filter(
   175              (report) => report?.reportID === currentReportId || ReportUtils.doesReportBelongToWorkspace(report, policyMemberAccountIDs, currentPolicyID),
   176          );
   177      }
   178      // There are a few properties that need to be calculated for the report which are used when sorting reports.
   179      reportsToDisplay.forEach((reportToDisplay) => {
   180          const report = reportToDisplay;
   181          const miniReport: MiniReport = {
   182              reportID: report?.reportID,
   183              displayName: ReportUtils.getReportName(report),
   184              lastVisibleActionCreated: report?.lastVisibleActionCreated,
   185          };
   186
   187          const isPinned = report?.isPinned ?? false;
   188          const reportAction = ReportActionsUtils.getReportAction(report?.parentReportID ?? '-1', report?.parentReportActionID ?? '-1');
   189          const reportNameValuePairs = ReportUtils.getReportNameValuePairs(report?.reportID);
   190          if (isPinned || ReportUtils.requiresAttentionFromCurrentUser(report, reportAction)) {
   191              pinnedAndGBRReports.push(miniReport);
   192          } else if (report?.hasErrorsOtherThanFailedReceipt) {
   193              errorReports.push(miniReport);
   194          } else if (hasValidDraftComment(report?.reportID ?? '-1')) {
   195              draftReports.push(miniReport);
   196          } else if (ReportUtils.isArchivedRoom(report, reportNameValuePairs)) {
   197              archivedReports.push(miniReport);
   198          } else {
   199              nonArchivedReports.push(miniReport);
   200          }
   201      });
   202
   203      // Sort each group of reports accordingly
   204      pinnedAndGBRReports.sort((a, b) => (a?.displayName && b?.displayName ? localeCompare(a.displayName, b.displayName) : 0));
   205      errorReports.sort((a, b) => (a?.displayName && b?.displayName ? localeCompare(a.displayName, b.displayName) : 0));
   206      draftReports.sort((a, b) => (a?.displayName && b?.displayName ? localeCompare(a.displayName, b.displayName) : 0));
   207
   208      if (isInDefaultMode) {
   209          nonArchivedReports.sort((a, b) => {
   210              const compareDates = a?.lastVisibleActionCreated && b?.lastVisibleActionCreated ? compareStringDates(b.lastVisibleActionCreated, a.lastVisibleActionCreated) : 0;
   211              if (compareDates) {
   212                  return compareDates;
   213              }
   214              const compareDisplayNames = a?.displayName && b?.displayName ? localeCompare(a.displayName, b.displayName) : 0;
   215              return compareDisplayNames;
   216          });
   217          // For archived reports ensure that most recent reports are at the top by reversing the order
   218          archivedReports.sort((a, b) => (a?.lastVisibleActionCreated && b?.lastVisibleActionCreated ? compareStringDates(b.lastVisibleActionCreated, a.lastVisibleActionCreated) : 0));
   219      } else {
   220          nonArchivedReports.sort((a, b) => (a?.displayName && b?.displayName ? localeCompare(a.displayName, b.displayName) : 0));
   221          archivedReports.sort((a, b) => (a?.displayName && b?.displayName ? localeCompare(a.displayName, b.displayName) : 0));
   222      }
   223
   224      // Now that we have all the reports grouped and sorted, they must be flattened into an array and only return the reportID.
   225      // The order the arrays are concatenated in matters and will determine the order that the groups are displayed in the sidebar.
   226
   227      const LHNReports = [...pinnedAndGBRReports, ...errorReports, ...draftReports, ...nonArchivedReports, ...archivedReports].map((report) => report?.reportID ?? '-1');
   228
   229      return LHNReports;
   230  }
   231
   232  /**
   233   * Gets all the data necessary for rendering an OptionRowLHN component
   234   */
   235  function getOptionData({
   236      report,
   237      reportActions,
   238      personalDetails,
   239      preferredLocale,
   240      policy,
   241      parentReportAction,
   242      hasViolations,
   243      lastMessageTextFromReport: lastMessageTextFromReportProp,
   244      transactionViolations,
   245      invoiceReceiverPolicy,
   246  }: {
   247      report: OnyxEntry<Report>;
   248      reportActions: OnyxEntry<ReportActions>;
   249      personalDetails: OnyxEntry<PersonalDetailsList>;
   250      preferredLocale: DeepValueOf<typeof CONST.LOCALES>;
   251      policy: OnyxEntry<Policy> | undefined;
   252      parentReportAction: OnyxEntry<ReportAction> | undefined;
   253      hasViolations: boolean;
   254      lastMessageTextFromReport?: string;
   255      invoiceReceiverPolicy?: OnyxEntry<Policy>;
   256      transactionViolations?: OnyxCollection<TransactionViolation[]>;
   257  }): ReportUtils.OptionData | undefined {
   258      // When a user signs out, Onyx is cleared. Due to the lazy rendering with a virtual list, it's possible for
   259      // this method to be called after the Onyx data has been cleared out. In that case, it's fine to do
   260      // a null check here and return early.
   261      if (!report || !personalDetails) {
   262          return;
   263      }
   264
   265      const result: ReportUtils.OptionData = {
   266          text: '',
   267          alternateText: undefined,
   268          allReportErrors: OptionsListUtils.getAllReportErrors(report, reportActions),
   269          brickRoadIndicator: null,
   270          tooltipText: null,
   271          subtitle: undefined,
   272          login: undefined,
   273          accountID: undefined,
   274          reportID: '',
   275          phoneNumber: undefined,
   276          isUnread: null,
   277          isUnreadWithMention: null,
   278          hasDraftComment: false,
   279          keyForList: undefined,
   280          searchText: undefined,
   281          isPinned: false,
   282          hasOutstandingChildRequest: false,
   283          hasOutstandingChildTask: false,
   284          hasParentAccess: undefined,
   285          isIOUReportOwner: null,
   286          isChatRoom: false,
   287          // eslint-disable-next-line @typescript-eslint/naming-convention
   288          private_isArchived: undefined,
   289          shouldShowSubscript: false,
   290          isPolicyExpenseChat: false,
   291          isMoneyRequestReport: false,
   292          isExpenseRequest: false,
   293          isWaitingOnBankAccount: false,
   294          isAllowedToComment: true,
   295          isDeletedParentAction: false,
   296          isConciergeChat: false,
   297      };
   298
   299      const participantAccountIDs = ReportUtils.getParticipantsAccountIDsForDisplay(report);
   300      const visibleParticipantAccountIDs = ReportUtils.getParticipantsAccountIDsForDisplay(report, true);
   301
   302      const participantPersonalDetailList = Object.values(OptionsListUtils.getPersonalDetailsForAccountIDs(participantAccountIDs, personalDetails));
   303      const personalDetail = participantPersonalDetailList[0] ?? {};
   304      const hasErrors = Object.keys(result.allReportErrors ?? {}).length !== 0;
   305
   306      result.isThread = ReportUtils.isChatThread(report);
   307      result.isChatRoom = ReportUtils.isChatRoom(report);
   308      result.isTaskReport = ReportUtils.isTaskReport(report);
   309      result.isInvoiceReport = ReportUtils.isInvoiceReport(report);
   310      result.parentReportAction = parentReportAction;
   311      // eslint-disable-next-line @typescript-eslint/naming-convention
   312      result.private_isArchived = report?.private_isArchived;
   313      result.isPolicyExpenseChat = ReportUtils.isPolicyExpenseChat(report);
   314      result.isExpenseRequest = ReportUtils.isExpenseRequest(report);
   315      result.isMoneyRequestReport = ReportUtils.isMoneyRequestReport(report);
   316      result.shouldShowSubscript = ReportUtils.shouldReportShowSubscript(report);
   317      result.pendingAction = report.pendingFields?.addWorkspaceRoom ?? report.pendingFields?.createChat;
   318      result.brickRoadIndicator = hasErrors || hasViolations ? CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR : '';
   319      const oneTransactionThreadReportID = ReportActionsUtils.getOneTransactionThreadReportID(report.reportID, ReportActionsUtils.getAllReportActions(report.reportID));
   320      if (oneTransactionThreadReportID) {
   321          const oneTransactionThreadReport = ReportUtils.getReport(oneTransactionThreadReportID);
   322
   323          if (
   324              ReportUtils.shouldDisplayTransactionThreadViolations(
   325                  oneTransactionThreadReport,
   326                  transactionViolations,
   327                  ReportActionsUtils.getAllReportActions(report.reportID)[oneTransactionThreadReport?.parentReportActionID ?? '-1'],
   328              )
   329          ) {
   330              result.brickRoadIndicator = CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR;
   331          }
   332      }
   333      result.ownerAccountID = report.ownerAccountID;
