    64                  <UnreadActionIndicator
    65                      reportActionID={report.reportID}
    66                      shouldHideThreadDividerLine={shouldHideThreadDividerLine}
    67                  />
    68              ) : (
    69                  <SpacerView
    70                      shouldShow={!shouldHideThreadDividerLine}
    71                      style={[!shouldHideThreadDividerLine ? styles.reportHorizontalRule : {}]}
    72                  />
    73              ),
    74          [shouldHideThreadDividerLine, report.reportID, styles.reportHorizontalRule],
    75      );
    76
    77      const contextMenuValue = useMemo(() => ({...contextValue, isDisabled: true}), [contextValue]);
    78
    79      if (ReportActionsUtils.isTransactionThread(parentReportAction)) {
    80          const isReversedTransaction = ReportActionsUtils.isReversedTransaction(parentReportAction);
    81
    82          if (ReportActionsUtils.isMessageDeleted(parentReportAction) || isReversedTransaction) {
    83              let message: TranslationPaths;
    84
    85              if (isReversedTransaction) {
    86                  message = 'parentReportAction.reversedTransaction';
    87              } else {
    88                  message = 'parentReportAction.deletedExpense';
    89              }
    90
    91              return (
    92                  <View style={[styles.pRelative]}>
    93                      <AnimatedEmptyStateBackground />
    94                      <OfflineWithFeedback pendingAction={parentReportAction?.pendingAction ?? null}>
    95                          <ReportActionItemSingle
    96                              action={parentReportAction}
    97                              showHeader
    98                              report={report}
    99                          >
   100                              <RenderHTML html={`<comment>${translate(message)}</comment>`} />
   101                          </ReportActionItemSingle>
   102                          <View style={styles.threadDividerLine} />
   103                      </OfflineWithFeedback>
   104                  </View>
   105              );
   106          }
   107
   108          return (
   109              <ShowContextMenuContext.Provider value={contextMenuValue}>
   110                  <View>
   111                      <MoneyRequestView
   112                          report={report}
   113                          shouldShowAnimatedBackground
   114                      />
   115                      {renderThreadDivider}
   116                  </View>
   117              </ShowContextMenuContext.Provider>
   118          );
   119      }
   120
   121      if (ReportUtils.isTaskReport(report)) {
   122          if (ReportUtils.isCanceledTaskReport(report, parentReportAction)) {
   123              return (
   124                  <View style={[styles.pRelative]}>
   125                      <AnimatedEmptyStateBackground />
   126                      <OfflineWithFeedback pendingAction={parentReportAction?.pendingAction}>
   127                          <ReportActionItemSingle
   128                              action={parentReportAction}
   129                              showHeader={draftMessage === undefined}
   130                              report={report}
   131                          >
   132                              <RenderHTML html={`<comment>${translate('parentReportAction.deletedTask')}</comment>`} />
   133                          </ReportActionItemSingle>
   134                      </OfflineWithFeedback>
   135                      <View style={styles.reportHorizontalRule} />
   136                  </View>
   137              );
   138          }
   139
   140          return (
   141              <View style={[styles.pRelative]}>
   142                  <AnimatedEmptyStateBackground />
   143                  <View>
   144                      <TaskView report={report} />
   145                      {renderThreadDivider}
   146                  </View>
   147              </View>
   148          );
   149      }
   150
   151      if (ReportUtils.isExpenseReport(report) || ReportUtils.isIOUReport(report) || ReportUtils.isInvoiceReport(report)) {
   152          return (
   153              <OfflineWithFeedback pendingAction={action.pendingAction}>
   154                  {!isEmptyObject(transactionThreadReport?.reportID) ? (
   155                      <>
   156                          <MoneyReportView
   157                              report={report}
   158                              policy={policy}
   159                              isCombinedReport
   160                              shouldShowTotal={transaction ? transactionCurrency !== report.currency : false}
   161                              shouldHideThreadDividerLine={shouldHideThreadDividerLine}
   162                          />
   163                          <ShowContextMenuContext.Provider value={contextMenuValue}>
   164                              <View>
   165                                  <MoneyRequestView
   166                                      report={transactionThreadReport}
   167                                      shouldShowAnimatedBackground={false}
   168                                  />
   169                                  {renderThreadDivider}
   170                              </View>
   171                          </ShowContextMenuContext.Provider>
   172                      </>
   173                  ) : (
   174                      <MoneyReportView
   175                          report={report}
   176                          policy={policy}
   177                          shouldHideThreadDividerLine={shouldHideThreadDividerLine}
   178                      />
   179                  )}
   180              </OfflineWithFeedback>
   181          );
   182      }
   183
   184      return (
   185          <ReportActionItemCreated
   186              reportID={report.reportID}
   187              policyID={report.policyID}
   188          />
   189      );
   190  }
