   192  ReportActionItemContentCreated.displayName = 'ReportActionItemContentCreated';
   193
   194  export default memo(
   195      ReportActionItemContentCreated,
   196      (prevProps, nextProps) =>
   197          lodashIsEqual(prevProps.contextValue, nextProps.contextValue) &&
   198          lodashIsEqual(prevProps.parentReportAction, nextProps.parentReportAction) &&
   199          prevProps.transactionID === nextProps.transactionID &&
